// GoFitr built-in common-foods database.
//
// Hand-authored from general nutrition knowledge (same spirit as the app's
// AI photo-estimate feature) — approximate, per-100g values, NOT sourced
// from a live API or lab data. Meant to cover common everyday
// foods/drinks/desserts/snacks from around the world so "Find Food" works
// without any network calls.
//
// Each entry: { name, category, kcal100, protein100, carbs100, fat100,
// fiber, saturatedFat, transFat, micros100 }. micros100 keys/units match
// MICRO_FIELDS in js/app.js exactly (mg/mcg per 100g).
//
// MK = the fixed micronutrient key order used by the m() shorthand below,
// so each food's micro data can be written as one compact array instead of
// a verbose object literal.
const MK = [
  "vitaminA", "vitaminC", "vitaminD", "vitaminE", "vitaminK",
  "vitaminB1", "vitaminB2", "vitaminB3", "vitaminB5", "vitaminB6", "vitaminB12",
  "calcium", "iron", "magnesium", "phosphorus", "potassium", "sodium",
  "zinc", "copper", "manganese",
];

function m(arr) {
  const o = {};
  MK.forEach((k, i) => { o[k] = arr[i] || 0; });
  return o;
}

function f(name, category, kcal, protein, carbs, fat, fiber, satFat, transFat, microsArr) {
  const micros100 = m(microsArr);
  // fiber/saturatedFat/transFat live inside micros100 (not as top-level
  // fields) because that's what showFoodDetail()/the Add Food handler in
  // js/app.js read them from — matches the shape USDA/OFF used to produce.
  micros100.fiber = fiber;
  micros100.saturatedFat = satFat;
  micros100.transFat = transFat;
  return {
    name, category,
    kcal100: kcal, protein100: protein, carbs100: carbs, fat100: fat,
    micros100,
  };
}

